fn decode_shift(s: Vec<char>) -> Vec<char> {
    // Requires that the input vector contains only lowercase alphabetic characters
    // Ensures that the output vector has the same length as the input vector
    // and that each character in the output is a valid lowercase alphabetic character
    #[verus::requires(s.iter().all(|&c| c >= 'a' && c <= 'z'))]
    #[verus::ensures(result.len() == s.len())]
    #[verus::ensures(result.iter().all(|&c| c >= 'a' && c <= 'z'))]
    let result: Vec<char> = s.into_iter()
        .map(|c| {
            // Calculate the new character by shifting left by 5 positions
            let shifted = ((c as u8 - b'a' + 26 - 5) % 26) + b'a';
            shifted as char
        })
        .collect();
    result
}

